#include <iostream>
#include <cmath>
#include <cstring>
#include <algorithm>

using namespace std;

using ll = long long;

const int MOD_CONST = 1000000007;

int current_mod = MOD_CONST;

int add_mod(int a, int b) { return ((a += b) < current_mod ? a : a - current_mod); }
int multiply_mod(int a, int b) { return (ll) a * b % current_mod; }
int fast_power(int base, int exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = multiply_mod(res, base);
        base = multiply_mod(base, base);
        exp >>= 1;
    }
    return res;
}

int P[1000001];

int find_beb(int a, int m) {
    memset(P, -1, sizeof P);
    int s = (int) sqrt(m);
    current_mod = m;
    int r = a % m;
    int d = fast_power(a, m - 2);
    for (int i = 0; i <= s; ++i) {
        if (P[r] == -1) P[r] = i;
        r = multiply_mod(r, d);
        if (r == 1) { current_mod = MOD_CONST; return i + 1; }
    }
    d = fast_power(a, s);
    r = d;
    for (int i = 1; i <= s; ++i) {
        if (P[r] > -1) {
            current_mod = MOD_CONST;
            return s * i + P[r];
        }
        r = multiply_mod(r, d);
    }
    return -1;
}

int main() {
    int p, k; cin >> p >> k;
    if (k == 1) cout << fast_power(p, p);
    else if (k == 0) cout << fast_power(p, p - 1);
    else cout << fast_power(p, (p - 1) / find_beb(k, p));
    return 0;
}
